/* Independent temporal-remix engine. No Akai presets or proprietary code. */
(()=>{class PerformanceDSP{
constructor(rate){this.rate=rate;this.capacity=Math.ceil(rate*8);this.ring=[new Float32Array(this.capacity),new Float32Array(this.capacity)];this.write=0;this.available=0;this.type=0;this.pos=0;this.wet=1;this.bpm=110;this.beats=4;this.loop=false;this.pending=null;this.speed=.5;this.repeatBeats=.5;this.repeatCount=2;this.reverseRepeat=false;this.capture=[new Float32Array(1),new Float32Array(1)]}
set(s){if(Number.isFinite(s.speed))this.speed=Math.max(.25,Math.min(2,s.speed));if(Number.isFinite(s.repeatBeats))this.repeatBeats=Math.max(1/16,Math.min(4,s.repeatBeats));if(Number.isFinite(s.repeatCount))this.repeatCount=Math.max(2,Math.min(8,Math.round(s.repeatCount)));if(s.reverseRepeat!==undefined)this.reverseRepeat=!!s.reverseRepeat;if(Number.isFinite(s.bpm))this.bpm=Math.max(40,Math.min(240,s.bpm));if(Number.isFinite(s.beats))this.beats=Math.max(1,Math.min(8,s.beats));if(Number.isFinite(s.wet))this.wet=Math.max(0,Math.min(1,s.wet));this.loop=!!s.loop;if(Number.isInteger(s.type)){const type=Math.max(0,Math.min(15,s.type));this.pending={type,delay:Math.max(0,Math.round(s.delay||0))}}}
activate(type){this.type=type;this.pos=0;this.length=Math.min(this.capacity,Math.round(this.rate*60/this.bpm*this.beats));if(this.capture[0].length!==this.length)this.capture=[new Float32Array(this.length),new Float32Array(this.length)];for(let ch=0;ch<2;ch++)for(let j=0;j<this.length;j++){const age=this.length-j;this.capture[ch][j]=age<=this.available?this.ring[ch][(this.write-age+this.capacity)%this.capacity]:0}}
read(ch,x){const d=this.capture[ch],n=d.length,p=((x%n)+n)%n,a=Math.floor(p),f=p-a;return d[a]*(1-f)+d[(a+1)%n]*f}
process(left,right,outLeft,outRight){for(let i=0;i<left.length;i++){if(this.pending&&this.pending.delay--<=0){this.activate(this.pending.type);this.pending=null}const l=left[i]||0,r=right?.[i]??l;this.ring[0][this.write]=l;this.ring[1][this.write]=r;this.write=(this.write+1)%this.capacity;this.available=Math.min(this.capacity,this.available+1);let a=l,b=r;const t=this.type,pos=this.pos,beat=this.rate*60/this.bpm;if(t){let x=pos,gate=1;switch(t){case 1:x=pos%beat;break;case 2:x=pos%(beat*this.repeatBeats);if(this.reverseRepeat)x=beat*this.repeatBeats-1-x;break;case 3:x=pos%(beat/4);break;case 4:x=pos%(beat/3);break;case 5:x=this.length-1-pos;break;case 6:x=pos*this.speed;break;case 7:x=pos*2;break;case 8:{const phase=(pos/beat)%2;x=(phase<1?phase:2-phase)*beat;break}case 9:case 10:case 11:{const duration=beat/(t===9?2:t===10?4:3);gate=pos%duration<duration*.5?1:0;break}case 12:x=pos-pos*pos/(2*this.length);break;case 13:x=beat/2-1-pos%(beat/2);break;case 14:{const size=beat*this.repeatBeats,n=Math.floor(pos/size),f=pos%size;x=Math.floor(n/this.repeatCount)%2?size-1-f:f;break}case 15:{const n=Math.floor(pos/(beat/2)),slice=((n*1103515245+12345)>>>8)%8;x=slice*beat/2+pos%(beat/2);break}}if(t>=9&&t<=11){a=l*gate;b=r*gate}else{a=this.read(0,x);b=this.read(1,x)}this.pos++;if(this.pos>=this.length){if(this.loop)this.pos=0;else this.type=0}}
outLeft[i]=l*(1-this.wet)+a*this.wet;outRight[i]=r*(1-this.wet)+b*this.wet}}
}
globalThis.PocketPerformanceDSP=PerformanceDSP;
})();
